const name = 'rednote';
const description = 'A friendly tool to help you access and interact with Xiaohongshu (RedNote) content through Model Context Protocol.';
const version = '0.2.3';
// Create server instance
const server = new mcp_js_1.McpServer({
    name,
    version,
    protocolVersion: '2024-11-05',
    capabilities: {
        tools: true,
        sampling: {},
        roots: {
            listChanged: true
        }
    }
});
// Register tools
server.tool('search_notes', '根据关键词搜索笔记', {
    keywords: zod_1.z.string().describe('搜索关键词'),
    limit: zod_1.z.number().optional().describe('返回结果数量限制')
