    logger_1.default.info(`Searching notes with keywords: ${keywords}, limit: ${limit}`);
    try {
        const tools = new rednoteTools_1.RedNoteTools();
        const notes = await tools.searchNotes(keywords, limit);
        logger_1.default.info(`Found ${notes.length} notes`);
        return {
            content: notes.map((note) => ({
                type: 'text',
                text: `标题: ${note.title}\n作者: ${note.author}\n内容: ${note.content}\n点赞: ${note.likes}\n评论: ${note.comments}\n链接: ${note.url}\n---`
            }))
        };
    }
    catch (error) {
        logger_1.default.error('Error searching notes:', error);
        throw error;
    }
});
server.tool('get_note_content', '获取笔记内容', {
    url: zod_1.z.string().describe('笔记 URL')
}, async ({ url }) => {
    logger_1.default.info(`Getting note content for URL: ${url}`);
    try {
        const tools = new rednoteTools_1.RedNoteTools();
        const note = await tools.getNoteContent(url);
        logger_1.default.info(`Successfully retrieved note: ${note.title}`);
        return {
            content: [
                {
                    type: 'text',
                    text: JSON.stringify(note)
                }
            ]
        };
    }
    catch (error) {
        logger_1.default.error('Error getting note content:', error);
        throw error;
    }
});
server.tool('get_note_comments', '获取笔记评论', {
    url: zod_1.z.string().describe('笔记 URL')
}, async ({ url }) => {
    logger_1.default.info(`Getting comments for URL: ${url}`);
    try {
        const tools = new rednoteTools_1.RedNoteTools();
        const comments = await tools.getNoteComments(url);
        logger_1.default.info(`Found ${comments.length} comments`);
        return {
            content: comments.map((comment) => ({
                type: 'text',
                text: `作者: ${comment.author}\n内容: ${comment.content}\n点赞: ${comment.likes}\n时间: ${comment.time}\n---`
            }))
        };
    }
    catch (error) {
        logger_1.default.error('Error getting note comments:', error);
        throw error;
    }
});
// Add login tool
server.tool('login', '登录小红书账号', {}, async () => {
    logger_1.default.info('Starting login process');
    const authManager = new authManager_1.AuthManager();
    try {
        await authManager.login();
        logger_1.default.info('Login successful');
        return {
            content: [
                {
                    type: 'text',
                    text: '登录成功！Cookie 已保存。'
                }
            ]
        };
    }
    catch (error) {
        logger_1.default.error('Login failed:', error);
        throw error;
    }
    finally {
        await authManager.cleanup();
    }
});
// Start the server
async function main() {
    logger_1.default.info('Starting RedNote MCP Server');
    // Start stdio logging
    const stopLogging = (0, stdioLogger_1.createStdioLogger)(`${logger_1.LOGS_DIR}/stdio.log`);
    const transport = new stdio_js_1.StdioServerTransport();
    await server.connect(transport);
    logger_1.default.info('RedNote MCP Server running on stdio');
    // Cleanup on process exit
    process.on('exit', () => {
        stopLogging();
    });
}
// 检查是否在 stdio 模式下运行
if (process.argv.includes('--stdio')) {
    main().catch((error) => {
        logger_1.default.error('Fatal error in main():', error);
        process.exit(1);
    });
}
else {
    const { Command } = require('commander');
    const program = new Command();
    program.name(name).description(description).version(version);
    program
        .command('init [timeout]')
        .description('Initialize and login to RedNote')
        .argument('[timeout]', 'Login timeout in seconds', (value) => parseInt(value, 10), 10)
        .usage('[options] [timeout]')
        .addHelpText('after', `
Examples:
  $ rednote-mcp init           # Login with default 10 seconds timeout
  $ rednote-mcp init 30        # Login with 30 seconds timeout
  $ rednote-mcp init --help    # Display help information

Notes:
  This command will launch a browser and open the RedNote login page.
  Please complete the login in the opened browser window.
  After successful login, the cookies will be automatically saved for future operations.
  The [timeout] parameter specifies the maximum waiting time (in seconds) for login, default is 10 seconds.
  The command will fail if the login is not completed within the specified timeout period.`)
        .action(async (timeout) => {
        logger_1.default.info(`Starting initialization process with timeout: ${timeout}s`);
        try {
            const authManager = new authManager_1.AuthManager();
            await authManager.login({ timeout });
            await authManager.cleanup();
            logger_1.default.info('Initialization successful');
            console.log('Login successful! Cookie has been saved.');
            process.exit(0);
        }
        catch (error) {
            logger_1.default.error('Error during initialization:', error);
            console.error('Error during initialization:', error);
            process.exit(1);
        }
    });
    program
        .command('pack-logs')
        .description('Pack all log files into a zip file')
        .action(async () => {
        try {
            const zipPath = await (0, logger_1.packLogs)();
            console.log(`日志已打包到: ${zipPath}`);
            process.exit(0);
        }
        catch (error) {
            console.error('打包日志失败:', error);
            process.exit(1);
        }
    });
    program
        .command('open-logs')
        .description('Open the logs directory in file explorer')
        .action(async () => {
        try {
            let command;
            switch (process.platform) {
                case 'darwin': // macOS
                    command = `open "${logger_1.LOGS_DIR}"`;
                    break;
                case 'win32': // Windows
                    command = `explorer "${logger_1.LOGS_DIR}"`;
                    break;
                case 'linux': // Linux
                    command = `xdg-open "${logger_1.LOGS_DIR}"`;
                    break;
                default:
                    throw new Error(`Unsupported platform: ${process.platform}`);
            }
            await execAsync(command);
            console.log(`日志目录已打开: ${logger_1.LOGS_DIR}`);
            process.exit(0);
        }
        catch (error) {
            console.error('打开日志目录失败:', error);
            process.exit(1);
        }
    });
    program.parse(process.argv);
}

